"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type ReactNode, useEffect, useRef, useState, useSyncExternalStore } from "react";

import { cn } from "@/lib/utils";

/** Says whether the action came from a press on the button or from the keyboard shortcut. */
export type ShortcutInput = "button" | "shortcut";

/** Props for a button that shows its keyboard shortcut and listens for it. */
export type ShortcutButtonProps = Omit<ComponentPropsWithoutRef<"button">, "children"> & {
  children: ReactNode;
  /**
   * Keys joined with "+", such as "mod+k", "shift+d" or "/". "mod" means
   * Command on Apple devices and Control elsewhere.
   */
  shortcut: string;
  /** Runs on a press of the button and on the shortcut. */
  onAction: (input: ShortcutInput) => void;
  /** How long the key cap stays down after the shortcut, in milliseconds. */
  pressFor?: number;
};

const PRESS: Transition = { duration: 0.1, ease: [0.165, 0.84, 0.44, 1] };
const INSTANT: Transition = { duration: 0 };
// The cap sinks by the height of the edge under it.
const CAP_TRAVEL = 2;

const MODIFIERS = ["mod", "shift", "alt"] as const;
type Modifier = (typeof MODIFIERS)[number];
const SYMBOLS = {
  apple: { mod: "⌘", shift: "⇧", alt: "⌥" },
  other: { mod: "Ctrl", shift: "Shift", alt: "Alt" },
} satisfies Record<string, Record<Modifier, string>>;
const KEY_NAMES = new Map([
  ["enter", "Enter"],
  ["escape", "Esc"],
  [" ", "Space"],
]);

function parse(shortcut: string) {
  const parts = shortcut.toLowerCase().split("+").map((part) => part.trim());
  const key = parts.at(-1) || "+";
  const modifiers = MODIFIERS.filter((modifier) => parts.slice(0, -1).includes(modifier));
  return { key: key === "space" ? " " : key, modifiers };
}

const isModifier = (modifiers: Modifier[], modifier: Modifier) => modifiers.includes(modifier);

// A plain key typed into a field is text, not a shortcut.
function isTyping(target: EventTarget | null) {
  if (!(target instanceof HTMLElement)) return false;
  return target.isContentEditable || ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName);
}

const subscribeToNothing = () => () => undefined;
const isAppleDevice = () => /mac|iphone|ipad/i.test(navigator.platform);

/**
 * A button that shows its keyboard shortcut as key caps. Pressing the real
 * keys runs the action and pushes the last cap down, so the person sees the
 * shortcut land on the button it belongs to.
 */
export function ShortcutButton({
  children,
  shortcut,
  onAction,
  pressFor = 160,
  className,
  disabled,
  onClick,
  onPointerDown,
  onPointerUp,
  onPointerLeave,
  onPointerCancel,
  ...buttonProps
}: ShortcutButtonProps) {
  const [keyDown, setKeyDown] = useState(false);
  const [held, setHeld] = useState(false);
  // The server cannot know the device, so the caps start with the Control names.
  const apple = useSyncExternalStore(subscribeToNothing, isAppleDevice, () => false);
  const timer = useRef<number | null>(null);
  const onActionRef = useRef(onAction);
  const reduceMotion = useReducedMotion();
  const { key, modifiers } = parse(shortcut);
  const modifierKey = modifiers.join("+");

  useEffect(() => {
    onActionRef.current = onAction;
  }, [onAction]);

  useEffect(() => {
    if (disabled) return;
    const wanted = modifierKey.split("+");
    const listen = (event: KeyboardEvent) => {
      if (event.repeat || event.key.toLowerCase() !== key) return;
      const mod = event.metaKey || event.ctrlKey;
      if (mod !== wanted.includes("mod") || event.altKey !== wanted.includes("alt")) return;
      // A symbol such as "?" already needs Shift, so Shift is checked only for letters and named keys.
      if (key.length > 1 || /[a-z0-9 ]/.test(key)) {
        if (event.shiftKey !== wanted.includes("shift")) return;
      }
      if (!mod && isTyping(event.target)) return;
      event.preventDefault();
      setKeyDown(true);
      // Timed, not tied to keyup: some systems send no keyup for a letter while Command is held.
      if (timer.current !== null) window.clearTimeout(timer.current);
      timer.current = window.setTimeout(() => setKeyDown(false), pressFor);
      onActionRef.current("shortcut");
    };
    window.addEventListener("keydown", listen);
    return () => {
      window.removeEventListener("keydown", listen);
      if (timer.current !== null) window.clearTimeout(timer.current);
      setKeyDown(false);
    };
  }, [disabled, key, modifierKey, pressFor]);

  const symbols = apple ? SYMBOLS.apple : SYMBOLS.other;
  const caps = [...modifiers.map((modifier) => symbols[modifier]), KEY_NAMES.get(key) ?? (key.length === 1 ? key.toUpperCase() : key)];
  const ariaKeys = [
    ...(isModifier(modifiers, "mod") ? [apple ? "Meta" : "Control"] : []),
    ...(isModifier(modifiers, "alt") ? ["Alt"] : []),
    ...(isModifier(modifiers, "shift") ? ["Shift"] : []),
    key === " " ? "Space" : key.length === 1 ? key.toUpperCase() : (KEY_NAMES.get(key) ?? key),
  ].join("+");
  const pressed = keyDown || held;

  return (
    <button
      {...buttonProps}
      type="button"
      disabled={disabled}
      aria-keyshortcuts={ariaKeys}
      data-pressed={pressed}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) onAction("button");
      }}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        setHeld(true);
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event);
        setHeld(false);
      }}
      onPointerLeave={(event) => {
        onPointerLeave?.(event);
        setHeld(false);
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event);
        setHeld(false);
      }}
      className={cn(
        "inline-flex min-h-11 cursor-pointer touch-manipulation items-center gap-3 rounded-full border border-border bg-background py-1 pr-2 pl-4 text-sm font-medium text-foreground outline-none",
        "motion-safe:transition-colors motion-safe:duration-150 hover:bg-muted",
        "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "disabled:cursor-not-allowed disabled:opacity-50",
        className,
      )}
    >
      {children}
      {/* Hidden from assistive technology: `aria-keyshortcuts` already names the keys. */}
      <span aria-hidden="true" className="flex items-center gap-1">
        {caps.map((cap, index) => {
          const down = pressed && index === caps.length - 1;
          return (
            // Each cap rests above a darker edge. Pressing moves the cap down onto it.
            <span key={cap} className="relative flex pb-0.5">
              <span className="absolute inset-x-0 top-0.5 bottom-0 rounded-md bg-muted-foreground/40" />
              <motion.kbd
                initial={false}
                animate={{ y: down && !reduceMotion ? CAP_TRAVEL : 0 }}
                transition={reduceMotion ? INSTANT : PRESS}
                className={cn(
                  "relative flex h-6 min-w-6 items-center justify-center rounded-md border border-border px-1.5 font-sans text-xs font-medium text-muted-foreground",
                  // The fill also changes, so the press still shows when motion is reduced.
                  down ? "bg-muted text-foreground" : "bg-background",
                )}
              >
                {cap}
              </motion.kbd>
            </span>
          );
        })}
      </span>
    </button>
  );
}
